let nextFrame = null;
const gradient = { addColorStop() {} };
const context = new Proxy({}, {
  get(_target, prop) {
    if (prop === 'createLinearGradient' || prop === 'createRadialGradient') return () => gradient;
    if (prop === 'canvas') return canvas;
    return () => {};
  },
  set() { return true; }
});
const canvas = { width: 0, height: 0, style: {}, getContext: () => context };
let clock = 0;
const sandbox = {
  console,
  Math,
  innerWidth: 1440,
  innerHeight: 900,
  devicePixelRatio: 2,
  performance: { now: () => clock },
  matchMedia: () => ({ matches: false }),
  addEventListener: () => {},
  requestAnimationFrame: cb => { nextFrame = cb; },
  document: {
    getElementById: () => canvas,
    createElement: () => ({ width: 0, height: 0, getContext: () => context })
  }
};
vm.runInNewContext(script, sandbox, { filename: 'index.html' });
for (let frame = 0; frame < 1080; frame++) {
  clock += 1000 / 60;
  const cb = nextFrame;
  if (typeof cb "'!== '"'function') throw new Error("'`Animation stopped at frame ${frame}`);
  nextFrame = null;
  cb(clock);
}
if (canvas.width !== 2880 || canvas.height !== 1800) throw new Error('"'Responsive canvas sizing failed');
console.log('runtime=ok frames=1080 duration=18s viewport=1440x900 dpr=2');
